begin;
create extension if not exists pgtap;
select plan(19);
insert into qarar_core.organizations(id,code,name_ar) values('84000000-0000-0000-0000-000000000001','temporary-test','اختبار كلمة مؤقتة');
insert into auth.users(id,email) values('84000000-0000-0000-0000-000000000002','admin84@example.test');
insert into qarar_iam.users(id,organization_id,email,full_name_ar,status,is_system_admin) values('84000000-0000-0000-0000-000000000002','84000000-0000-0000-0000-000000000001','admin84@example.test','مدير','active',true);
insert into auth.users(id,email,encrypted_password) values('84000000-0000-0000-0000-000000000003','temp84@example.test','baseline-hash');
set local request.jwt.claims='{"role":"service_role"}';
set local role service_role;
select lives_ok($$select api_v1.service_finalize_temporary_user('84000000-0000-0000-0000-000000000002','84000000-0000-0000-0000-000000000003','temp84@example.test','مستخدم مؤقت',null,null,null,null,null,null)$$,'system admin finalizes direct account');
reset role;
select ok((select must_change_password from qarar_iam.users where id='84000000-0000-0000-0000-000000000003'),'account requires replacement');
set local request.jwt.claims='{"role":"authenticated","sub":"84000000-0000-0000-0000-000000000003","session_id":"84000000-0000-0000-0000-000000000004"}';
set local role authenticated;
select is(qarar_iam.current_organization_id(),null::uuid,'pending account has no tenant access');
select is(api_v1.get_current_user_access_context(),null::jsonb,'pending identity has no application access context');
select throws_ok($$select api_v1.service_get_temporary_password_state('84000000-0000-0000-0000-000000000003')$$,'42501',null,'service status is not exposed to authenticated clients');
reset role;
set local request.jwt.claims='{"role":"service_role"}';
set local role service_role;
select lives_ok($$select api_v1.service_claim_temporary_password('84000000-0000-0000-0000-000000000003','84000000-0000-0000-0000-000000000005')$$,'claim is acquired');
select throws_ok($$select api_v1.service_claim_temporary_password('84000000-0000-0000-0000-000000000003','84000000-0000-0000-0000-000000000006')$$,'40001',null,'competing claim is denied');
select throws_ok($$select api_v1.service_finish_temporary_password('84000000-0000-0000-0000-000000000003','84000000-0000-0000-0000-000000000005')$$,'22023',null,'unchanged Auth password cannot clear requirement');
reset role;
update auth.users set encrypted_password='new-hash' where id='84000000-0000-0000-0000-000000000003';
insert into auth.sessions(id,user_id,created_at,updated_at) values('84000000-0000-0000-0000-000000000004','84000000-0000-0000-0000-000000000003',now(),now());
set local role service_role;
select lives_ok($$select api_v1.service_finish_temporary_password('84000000-0000-0000-0000-000000000003','84000000-0000-0000-0000-000000000005')$$,'completion is atomic');
select is(api_v1.service_finish_temporary_password('84000000-0000-0000-0000-000000000003','84000000-0000-0000-0000-000000000005')->>'completed','true','completion receipt is replayable');
reset role;
select ok(not exists(select 1 from auth.sessions where user_id='84000000-0000-0000-0000-000000000003'),'temporary Auth sessions are revoked');
set local request.jwt.claims='{"role":"authenticated","sub":"84000000-0000-0000-0000-000000000003","session_id":"84000000-0000-0000-0000-000000000004"}';
set local role authenticated;
select is(qarar_iam.current_organization_id(),null::uuid,'revoked temporary JWT still has no tenant access');
select is(api_v1.get_current_user_access_context(),null::jsonb,'old temporary JWT has no application access context');
reset role;
insert into auth.sessions(id,user_id,created_at,updated_at) values('84000000-0000-0000-0000-000000000007','84000000-0000-0000-0000-000000000003',now(),now());
set local request.jwt.claims='{"role":"authenticated","sub":"84000000-0000-0000-0000-000000000003","session_id":"84000000-0000-0000-0000-000000000007"}';
set local role authenticated;
select is(qarar_iam.current_organization_id(),'84000000-0000-0000-0000-000000000001'::uuid,'new live session has tenant access');
select is(api_v1.get_current_user_access_context()->>'organization_id','84000000-0000-0000-0000-000000000001','new live session receives the application context');
reset role;
select ok(exists(select 1 from qarar_audit.audit_logs where actor_user_id='84000000-0000-0000-0000-000000000003' and action='iam.temporary_password.complete'),'completion audit names the user');
set local request.jwt.claims='{"role":"authenticated","sub":"84000000-0000-0000-0000-000000000002"}';
set local role authenticated;
select is(qarar_iam.current_organization_id(),'84000000-0000-0000-0000-000000000001'::uuid,'existing accounts without Auth session_id remain compatible');
reset role;
select ok(not exists(select 1 from qarar_audit.audit_logs where organization_id='84000000-0000-0000-0000-000000000001' and (coalesce(metadata->'old','{}'::jsonb) ? 'temporary_password_hash' or coalesce(metadata->'new','{}'::jsonb) ? 'temporary_password_hash')),'password baseline never enters row audit');
select ok(not exists(select 1 from qarar_audit.audit_logs where organization_id='84000000-0000-0000-0000-000000000001' and (coalesce(metadata->'old','{}'::jsonb) ? 'password_change_claim' or coalesce(metadata->'new','{}'::jsonb) ? 'password_change_claim')),'claim token never enters row audit');
select * from finish();
rollback;
